#!/usr/bin/env python3
"""Stage 4-7 Temporal Ego-centric World Model v4 (Road/Non-Road + Lane + Improved 1280px Detector)."""

import base64
import json
import shutil
import subprocess
import sys
import urllib.request
import zipfile
import zlib
from pathlib import Path

ROAD_LANE_B64 = ''
TRACK_UTILS_B64 = ''
WORLD_MODEL_B64 = ''
WORLD_VIS_B64 = ''
VALIDATION_B64 = ''

DEMO_SEQS = ["0015", "0019"]
S3_LABEL_URL = "https://s3.eu-central-1.amazonaws.com/avg-kitti/data_tracking_label_2.zip"
S3_CALIB_URL = "https://s3.eu-central-1.amazonaws.com/avg-kitti/data_tracking_calib.zip"
S3_OXTS_URL = "https://s3.eu-central-1.amazonaws.com/avg-kitti/data_tracking_oxts.zip"


def download_file(url: str, dst: Path) -> None:
    dst.parent.mkdir(parents=True, exist_ok=True)
    if dst.exists() and dst.stat().st_size > 0:
        return
    curl = shutil.which("curl")
    if curl:
        subprocess.run([curl, "-L", "-C", "-", "--retry", "5", "--retry-delay", "5", "-o", str(dst), url], check=True)
    else:
        with urllib.request.urlopen(url) as resp, open(dst, "wb") as out:
            shutil.copyfileobj(resp, out)


def find_kitti_image_dir() -> Path:
    for p in sorted(Path("/kaggle/input").rglob("image_02")):
        if p.is_dir() and "training" in p.parts and (p / "0015").is_dir() and (p / "0019").is_dir():
            return p
    raise FileNotFoundError("KITTI Tracking training/image_02 not found")


def main() -> None:
    work = Path("/kaggle/working")
    out_dir = work / "v4_world_outputs"
    out_dir.mkdir(parents=True, exist_ok=True)
    src_dir = work / "src"
    src_dir.mkdir(parents=True, exist_ok=True)
    (src_dir / "__init__.py").write_text("", encoding="utf-8")
    (src_dir / "road_lane.py").write_bytes(zlib.decompress(base64.b64decode(ROAD_LANE_B64)))
    (src_dir / "track_utils.py").write_bytes(zlib.decompress(base64.b64decode(TRACK_UTILS_B64)))
    (src_dir / "world_model.py").write_bytes(zlib.decompress(base64.b64decode(WORLD_MODEL_B64)))
    (src_dir / "world_visualizer.py").write_bytes(zlib.decompress(base64.b64decode(WORLD_VIS_B64)))
    (src_dir / "validation_experiments.py").write_bytes(zlib.decompress(base64.b64decode(VALIDATION_B64)))
    sys.path.insert(0, str(src_dir))

    from world_visualizer import generate_world_model_demo
    from validation_experiments import run_all_validations

    tmp = Path("/tmp/kitti_v4_wm")
    label_zip = tmp / "data_tracking_label_2.zip"
    calib_zip = tmp / "data_tracking_calib.zip"
    oxts_zip = tmp / "data_tracking_oxts.zip"
    download_file(S3_LABEL_URL, label_zip)
    download_file(S3_CALIB_URL, calib_zip)
    download_file(S3_OXTS_URL, oxts_zip)
    with zipfile.ZipFile(label_zip, "r") as zf: zf.extractall(tmp / "labels")
    with zipfile.ZipFile(calib_zip, "r") as zf: zf.extractall(tmp / "calib")
    with zipfile.ZipFile(oxts_zip, "r") as zf: zf.extractall(tmp / "oxts")

    image_dir = find_kitti_image_dir()
    summaries = {}
    validations = {}
    road_ctx_stats = {}

    for seq in DEMO_SEQS:
        traj_matches = list(Path("/kaggle/input").rglob(f"track_{seq}/trajectories.csv"))
        mask_matches = list(Path("/kaggle/input").rglob(f"track_{seq}/trajectories_masks.json"))
        rl_matches = list(Path("/kaggle/input").rglob(f"road_lane_{seq}.json"))
        if not traj_matches:
            raise FileNotFoundError(f"Missing track_{seq}/trajectories.csv in /kaggle/input")
        if not rl_matches:
            raise FileNotFoundError(f"Missing road_lane_{seq}.json in /kaggle/input")
        traj_csv = traj_matches[0]
        masks_json = mask_matches[0] if mask_matches else None
        rl_json = rl_matches[0]

        calib_p = [p for p in (tmp / "calib").rglob(f"{seq}.txt") if "training" in p.parts][0]
        label_p = [p for p in (tmp / "labels").rglob(f"{seq}.txt") if "training" in p.parts][0]
        oxts_p = [p for p in (tmp / "oxts").rglob(f"{seq}.txt") if "training" in p.parts][0]

        seq_imgs = tmp / f"raw_{seq}"
        seq_imgs.mkdir(parents=True, exist_ok=True)
        for p in sorted((image_dir / seq).glob("*.png")):
            shutil.copy2(p, seq_imgs / p.name)

        for tag, max_fr, staged in ((f"{seq}_staged", 80, True), (f"{seq}_full", None, False)):
            w_out = out_dir / f"world_model_{tag}"
            wsum = generate_world_model_demo(
                images_dir=seq_imgs,
                trajectories_csv=traj_csv,
                output_dir=w_out,
                calib_file=calib_p,
                label_file=label_p,
                oxts_file=oxts_p,
                masks_json=masks_json,
                road_lane_json=rl_json,
                seq_id=seq,
                fps=10.0,
                max_frames=max_fr,
                staged_demo=staged,
            )
            summaries[tag] = wsum

            if not staged:
                tl = json.loads((w_out / f"world_model_timeline_{seq}.json").read_text(encoding="utf-8"))
                total_objs = 0
                in_lane_cnt = 0
                on_road_cnt = 0
                off_road_cnt = 0
                for fr in tl:
                    for o in fr["present_world"]["objects"]:
                        rc = o.get("road_context")
                        if not rc:
                            continue
                        total_objs += 1
                        if rc.get("in_ego_lane"):
                            in_lane_cnt += 1
                        elif rc.get("on_road"):
                            on_road_cnt += 1
                        else:
                            off_road_cnt += 1
                road_ctx_stats[seq] = {
                    "total_object_observations": total_objs,
                    "ego_lane_objects": in_lane_cnt,
                    "adjacent_road_objects": on_road_cnt,
                    "non_road_objects": off_road_cnt,
                }

        val_res = run_all_validations(seq_id=seq, trajectories_csv=traj_csv, calib_file=calib_p, oxts_file=oxts_p, label_file=label_p, fps=10.0)
        validations[seq] = val_res
        (out_dir / f"validation_{seq}.json").write_text(json.dumps(val_res, indent=2), encoding="utf-8")

    (out_dir / "world_model_all_summaries.json").write_text(json.dumps(summaries, indent=2), encoding="utf-8")
    (out_dir / "road_context_stats.json").write_text(json.dumps(road_ctx_stats, indent=2), encoding="utf-8")
    (out_dir / "validation_rq1_rq2_rq3_rq4.json").write_text(json.dumps(validations, indent=2), encoding="utf-8")
    print("[DONE v4 World Model]", json.dumps(road_ctx_stats, indent=2), flush=True)


if __name__ == "__main__":
    main()
